import { BrandAvatarList, ComparisonLine } from 'components';
import type { BrandAvatarItemProps } from 'components/BrandAvatar/Components/BrandAvatarItem/interface';
import { Waterfall } from 'components/Chart/Bar/Waterfall';
import { WATERFALL_LAYOUT } from 'pages/pillars/PortfolioBrand/utils/countryContributionChartData';

import type { BeerEvolutionBreakdownData } from '../../../../types';
import {
  StyledAvatarContainer,
  StyledBeerEvolutionContent,
  StyledWaterfallContainer,
} from './BeerEvolutionBreakdownSection.styles';
import { resolveBeerEvolutionTestId } from './beerEvolutionBreakdownSection.utils';

interface BeerEvolutionReadyContentProps {
  data: BeerEvolutionBreakdownData;
  dataTestId?: string;
  chartValues: number[];
  chartLabelsLength: number;
  waterfallLabels: string[];
  brandAvatarData: BrandAvatarItemProps[];
}

export const BeerEvolutionReadyContent = ({
  data,
  dataTestId,
  chartValues,
  chartLabelsLength,
  waterfallLabels,
  brandAvatarData,
}: BeerEvolutionReadyContentProps) => (
  <StyledBeerEvolutionContent>
    <StyledWaterfallContainer
      data-testid={resolveBeerEvolutionTestId(
        dataTestId,
        'waterfall-container',
        'beer-evolution-waterfall-container',
      )}
    >
      <Waterfall
        values={chartValues}
        labels={waterfallLabels}
        formattedData={data.formattedData}
        showLabels={false}
        size="small"
        options={{
          layout: { padding: { ...WATERFALL_LAYOUT.padding } },
          plugins: {
            connectBars: { color: 'rgba(20, 20, 20, 0.5)' },
          },
        }}
        colors={WATERFALL_LAYOUT.barColors}
        decimalPlaces={1}
        stripedIndexes={data.stripedIndexes ?? []}
        specialIndexes={data.specialIndexes}
        dataTestId={resolveBeerEvolutionTestId(
          dataTestId,
          'waterfall',
          'beer-evolution-waterfall',
        )}
      />
    </StyledWaterfallContainer>

    {brandAvatarData.length > 0 ? (
      <StyledAvatarContainer>
        <BrandAvatarList
          data={brandAvatarData}
          length={chartLabelsLength}
          borderConfig={{ marginLeft: 0, marginRight: 0 }}
          gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
          dataTestId={resolveBeerEvolutionTestId(
            dataTestId,
            'brand-avatars',
            'beer-evolution-brand-avatars',
          )}
        />
      </StyledAvatarContainer>
    ) : null}

    {data.comparisonLine?.data ? (
      <ComparisonLine
        data={data.comparisonLine.data}
        gridColumnsLength={chartLabelsLength}
        gridConfig={{ paddingLeft: 0, paddingRight: 0 }}
        borderConfig={{ marginLeft: 20, marginRight: 16 }}
        dataTestId={resolveBeerEvolutionTestId(
          dataTestId,
          'comparison-table',
          'beer-evolution-comparison-table',
        )}
      />
    ) : null}
  </StyledBeerEvolutionContent>
);
